import { ChangeDetectionStrategy, Component, Input, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { TranslationService } from '../../../core/services/translation.service';

interface TitlePart {
	text: string;
	style?: 'bold';
	break?: boolean | string;
}

@Component({
	selector: 'app-what-you-get',
	standalone: true,
	imports: [CommonModule, TranslateModule],
	templateUrl: './what-you-get.component.html',
	styleUrl: './what-you-get.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WhatYouGetComponent {

	@Input() sectionKey = 'WHATYOUGET.BRANDING';

	constructor(
		public translationService: TranslationService,
		private translate: TranslateService,
	) {
		effect(() => {
			this.translationService.currentLang();
		});
	}

	keyExists(key: string): boolean {
		const value = this.translate.instant(key);

		return value !== key && value !== undefined && value !== null && value !== '';
	}

	getTitleParts(): TitlePart[] {
		const parts = this.translate.instant(this.sectionKey + '.TITLE_PARTS');

		return Array.isArray(parts) ? parts : [];
	}

	getListItems(): string[] {
		const list = this.translate.instant(this.sectionKey + '.LIST');

		return list && typeof list === 'object' ? Object.keys(list) : [];
	}

	getTags(item: string): string[] {
		const tags = this.translate.instant(this.sectionKey + '.LIST.' + item + '.TAGS');

		return Array.isArray(tags) ? tags : [];
	}
}
